description:
Develop a simple 4-bit calculator that performs basic arithmetic operations. The module takes two 4-bit inputs, `a` and `b`, along with a 2-bit control signal, `ctrl`, to select the desired operation. Based on the value of `ctrl`, the calculator can perform addition, subtraction, multiplication, or division on the inputs and output the result as a 4-bit value.
module top_module(
  input [3:0] a, b,
  input [1:0] ctrl,
  output reg [3:0] result
);

testbench:
`timescale 1ns/1ps

module top_module_tb;

    // Testbench signals (combinational circuit)
    reg [3:0] a;
    reg [3:0] b;
    reg [1:0] ctrl;
    wire [3:0] result;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .a(a),
        .b(b),
        .ctrl(ctrl),
        .result(result)
    );
    task testcase001;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Addition (3 + 5)", test_num);
            a = 4'd3;
            b = 4'd5;
            ctrl = 2'b00;
            #1;

            check_outputs(4'd8);
        end
        endtask

    task testcase002;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Addition Overflow (10 + 10)", test_num);
            a = 4'd10;
            b = 4'd10;
            ctrl = 2'b00;
            #1;

            check_outputs(4'd4);
        end
        endtask

    task testcase003;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Subtraction (10 - 4)", test_num);
            a = 4'd10;
            b = 4'd4;
            ctrl = 2'b01;
            #1;

            check_outputs(4'd6);
        end
        endtask

    task testcase004;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Subtraction Negative (4 - 10)", test_num);
            a = 4'd4;
            b = 4'd10;
            ctrl = 2'b01;
            #1;

            check_outputs(4'd10);
        end
        endtask

    task testcase005;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Multiplication (2 * 3)", test_num);
            a = 4'd2;
            b = 4'd3;
            ctrl = 2'b10;
            #1;

            check_outputs(4'd6);
        end
        endtask

    task testcase006;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Multiplication Overflow (4 * 5)", test_num);
            a = 4'd4;
            b = 4'd5;
            ctrl = 2'b10;
            #1;

            check_outputs(4'd4);
        end
        endtask

    task testcase007;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Division (12 / 3)", test_num);
            a = 4'd12;
            b = 4'd3;
            ctrl = 2'b11;
            #1;

            check_outputs(4'd4);
        end
        endtask

    task testcase008;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Division with Remainder (7 / 2)", test_num);
            a = 4'd7;
            b = 4'd2;
            ctrl = 2'b11;
            #1;

            check_outputs(4'd3);
        end
        endtask

    task testcase009;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Division (3 / 5)", test_num);
            a = 4'd3;
            b = 4'd5;
            ctrl = 2'b11;
            #1;

            check_outputs(4'd0);
        end
        endtask

    task testcase010;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Max Value Addition (15 + 1)", test_num);
            a = 4'd15;
            b = 4'd1;
            ctrl = 2'b00;
            #1;

            check_outputs(4'd0);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("top_module Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();
        testcase007();
        testcase008();
        testcase009();
        testcase010();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [3:0] expected_result;
        begin
            #1; // Small delay for combinational logic to settle
            if (expected_result === (expected_result ^ result ^ expected_result)) begin
                $display("PASS");
                $display("  Outputs: result=%h",
                         result);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: result=%h",
                         expected_result);
                $display("  Got:      result=%h",
                         result);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

endmodule

