  if(CaptureDR | ShiftDR) 
  Latch<=SelectedInput; 
 end 
 always @ (negedge TCK) 
 begin 
  ToNextBSCell<=Latch; 
 end 
 always @ (negedge TCK) 
 begin 
  if(UpdateDR) 
  ShiftedControl<=ToNextBSCell; 
 end 
 wire MuxedSignal = extest? ShiftedControl : FromCore; 
 assign BiDirPin = FromOutputEnable? MuxedSignal : 1'bz; 
 assign ToCore = BiDirPin; 
 endmodule

