module top_module(input  [31:0] MemOut,
                    input  [1:0]  MemSize,
                    input         LoadUnsigned,
                    input  [31:0] Address, 
                    output reg [31:0] Result);reg [15:0] Half;
  reg [7:0] Single;

  always @(*) begin
    Half = ~Address[1] ? MemOut[31:16] : MemOut[15:0];
    Single = ~Address[0] ? Half[15:8] : Half[7:0];

    case (MemSize)
      2'b00: Result = (LoadUnsigned | ~Single[7]) ? { 24'b0, Single } : { 24'hFFFFFF, Single };
      2'b01: Result = (LoadUnsigned | ~Half[15]) ? { 16'b0, Half } : { 16'hFFFF, Half };
      2'b11: Result = MemOut;
    endcase

  end

endmodule

