    always @ (posedge clk) begin
        if (I[3]) begin
            stage1_out <= 2'b11; // Set based on input priority
        end else if (I[2]) begin
            stage1_out <= 2'b10; 
        end else if (I[1]) begin
            stage1_out <= 2'b01; 
