module falling_edge_detector(
    input clk,
    input reset,
    input [3:0] in,
    output reg [3:0] out);

    reg [3:0] in_last;

    always @(posedge clk or posedge reset) begin
        if (reset)
            out <= 4'b0;
        else begin
            in_last <= in;
            out <= out | (in_last & ~in);
        end
    end
endmodule

