    input        wr_en,
    input        rd_clk,
    input        rd_en,
    input        rst_n,
    input  [7:0] din,
    output reg [7:0] dout,  // Changed to reg since it's driven in always block
    output       empty,
    output       full
);reg [7:0] buffer [0:15];
