reg [3:0] rd_ptr;          // Changed to 4 bits for proper indexing
reg        empty_reg;      // Use separate regs for internal use
reg        full_reg;       // Use separate regs for internal use

// Assign outputs
assign empty = empty_reg;
assign full = full_reg;

