    if (~rst_n) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        empty_reg <= 1;
        full_reg <= 0;
    end else if (wr_en && ~full_reg) begin
        buffer[wr_ptr] <= din;
        wr_ptr <= wr_ptr + 1;
        if (wr_ptr == 15) full_reg <= 1; // Adjust to handle wrapping properly
        empty_reg <= 0; 
    end
end

always @(posedge rd_clk or negedge rst_n) begin
    if (~rst_n) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        empty_reg <= 1;
        full_reg <= 0;
    end else if (rd_en && ~empty_reg) begin
        dout <= buffer[rd_ptr];
        rd_ptr <= rd_ptr + 1;
        if (rd_ptr == 15) empty_reg <= 1; // Adjust to handle wrapping properly
        full_reg <= 0; 
    end
end

endmodule

