module top_module(
    input CLK,
    input EN,
    input TE,
    output ENCLK
);wire gated_clk;
    wire latch_out; // Output from the latch

    // Gated clock logic
    assign gated_clk = (EN & ~TE) ? 1'b0 : CLK;

    // Simple D flip-flop as a placeholder for TLATNTSCAX2TS
    reg DFF;
    always @(posedge gated_clk or posedge TE) begin
        if (TE) begin
            DFF <= 1'b0; // reset condition when TE is high
        end else if (EN) begin
            DFF <= 1'b1; // latch the clock when EN is high
        end
    end

    assign ENCLK = DFF;

endmodule

