    input [7:0] in,
    output reg [2:0] pos
);reg [7:0] in_reg [2:0];

always @(posedge clk) begin
    in_reg[0] <= in;
    in_reg[1] <= in_reg[0];
    in_reg[2] <= in_reg[1];

    if (in_reg[0] == 0) begin
        pos <= 0;
    end else if (in_reg[0][7] == 1) begin
        pos <= 7;
    end else if (in_reg[0][6] == 1) begin
