    end else if (in_reg[0][4] == 1) begin
        pos <= 4;
    end else if (in_reg[0][3] == 1) begin
        pos <= 3;
    end else if (in_reg[0][2] == 1) begin
        pos <= 2;
    end else if (in_reg[0][1] == 1) begin
        pos <= 1;
    end else if (in_reg[0][0] == 1) begin
        pos <= 0;
