description:
Implement the Verilog module based on the following description.
Build a 4-bit binary counter with asynchronous active low reset signal and an up/down control signal. When up_down is high, the counter counts up; when low, it counts down.
// (1) reset_n: Resets the counter to 4'b0000 when low.
// (2) up_down: Controls the counting direction. If high, count up; if low, count down.
// (3) q: The value of the counter.

module top_module(
    input clk,
    input reset_n,
    input up_down,
    output reg [3:0] q);

code:
module top_module(
    input clk,
    input reset_n,
    input up_down,
    output reg [3:0] q
);

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            // Asynchronous reset: Reset the counter to 4'b0000
            q <= 4'b0000;
        end else begin
            if (up_down) begin
                // Count up
                q <= q + 1;
            end else begin
                // Count down
                q <= q - 1;
            end
        end
    end

endmodule

