Design a 4-bit binary ones counter that counts the number of '1' bits in a 16-bit input vector. The module takes a 16-bit input (`data_in`) and outputs a 4-bit value (`ones_count`) representing the total count of '1' bits present in the input. It utilizes a bitwise shift and loop to evaluate each bit of the input, incrementing the count accordingly whenever a '1' is detected.
module top_module(
    input [15:0] data_in,
    output reg [3:0] ones_count
);

code:
module top_module(
    input [15:0] data_in,
    output reg [3:0] ones_count
);integer i;
    reg [15:0] temp;

    always @ (data_in) begin
        temp = data_in;
        ones_count = 0;
        for (i = 0; i < 16; i = i + 1) begin
            if (temp[0] == 1'b1) begin
                ones_count = ones_count + 1;
            end
            temp = temp >> 1;
        end
    end

endmodule

